package Java;

public class DoWhileLoop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		   
		  int count = 1;
		  do {
			   System.out.println("The value of count is :" + count);
			   count++;
			  
		  }while(count<=30);

	}//end of main method

}//end of class
